def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    banned = list(set(banned))
    # Build Aho-Corasick automaton
    goto = [{}]
    fail = [0]
    bad = [False]
    for w in banned:
        cur = 0
        for ch in w:
            if ch not in goto[cur]:
                goto.append({})
                fail.append(0)
                bad.append(False)
                goto[cur][ch] = len(goto) - 1
            cur = goto[cur][ch]
        bad[cur] = True
    chars = list(dict.fromkeys(alphabet))
    # BFS
    from collections import deque
    q = deque()
    for ch in chars:
        if ch in goto[0]:
            nxt = goto[0][ch]
            fail[nxt] = 0
            q.append(nxt)
    trans = [dict() for _ in goto]
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        bad[u] = bad[u] or bad[fail[u]]
        for ch in chars:
            if ch in goto[u]:
                v = goto[u][ch]
                f = fail[u]
                fail[v] = trans[f][ch] if ch in trans[f] else 0
                q.append(v)
    # compute transitions in BFS order (root first)
    def full(u):
        for ch in chars:
            if ch in goto[u]:
                trans[u][ch] = goto[u][ch]
            elif u == 0:
                trans[u][ch] = 0
            else:
                trans[u][ch] = trans[fail[u]][ch]
    full(0)
    for u in order:
        full(u)
    # Note: fail[v] computed above used trans[f], where f has smaller depth,
    # but trans[f] may not yet be filled; recompute fail properly below.
    # Recompute properly:
    fail = [0] * len(goto)
    trans = [dict() for _ in goto]
    full(0)
    q = deque()
    for ch in chars:
        if ch in goto[0]:
            q.append(goto[0][ch])
    while q:
        u = q.popleft()
        full(u)
        for ch in chars:
            if ch in goto[u]:
                v = goto[u][ch]
                fail[v] = trans[fail[u]][ch]
                q.append(v)
    # bad propagation via fail links (BFS order guarantees fail processed earlier)
    q = deque()
    for ch in chars:
        if ch in goto[0]:
            q.append(goto[0][ch])
    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for ch in chars:
            if ch in goto[u]:
                q.append(goto[u][ch])
    if bad[0]:
        return 0
    good = [i for i in range(len(goto)) if not bad[i]]
    idx = {s: i for i, s in enumerate(good)}
    m = len(good)
    M = [[0] * m for _ in range(m)]
    for s in good:
        for ch in chars:
            t = trans[s][ch]
            if not bad[t]:
                M[idx[s]][idx[t]] += 1

    def mul(A, B):
        C = [[0] * m for _ in range(m)]
        for i in range(m):
            Ai = A[i]
            Ci = C[i]
            for k in range(m):
                a = Ai[k]
                if a:
                    Bk = B[k]
                    for j in range(m):
                        Ci[j] += a * Bk[j]
            for j in range(m):
                Ci[j] %= MOD
        return C

    # vector times matrix power
    vec = [0] * m
    vec[idx[0]] = 1
    e = n
    P = M
    while e:
        if e & 1:
            nv = [0] * m
            for i in range(m):
                v = vec[i]
                if v:
                    row = P[i]
                    for j in range(m):
                        nv[j] += v * row[j]
            vec = [x % MOD for x in nv]
        e >>= 1
        if e:
            P = mul(P, P)
    return sum(vec) % MOD
